(()=>{const gallery=document.querySelector('.hero-gallery');if(!gallery)return;const slides=[['guitar','گیتار','سازهای زهی','استاد حاجیان · استاد سلیمانی (فلامنکو)'],['violin','ویولن','سازهای آرشه‌ای','استاد اکبری'],['piano','پیانو','سازهای کلاویه‌ای','استاد فروقی'],['tar','تار','سازهای ایرانی','استاد جعفری'],['trumpet','ترومپت','سازهای بادی','استاد اکبری · استاد محسن اکبری']];const photos=[...gallery.querySelectorAll('.gallery-photo')],dots=[...gallery.querySelectorAll('[data-gallery]')],pause=document.getElementById('gallery-pause'),reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let index=0,paused=reduced.matches,timer=null;function show(i){index=(i+slides.length)%slides.length;const [tone,name,family,teacher]=slides[index];photos.forEach((p,n)=>{p.classList.toggle('is-active',n===index);p.setAttribute('aria-hidden',String(n!==index))});dots.forEach((d,n)=>{d.classList.toggle('current',n===index);d.setAttribute('aria-pressed',String(n===index))});gallery.dataset.tone=tone;document.getElementById('gallery-name').textContent=name;document.getElementById('gallery-family').textContent=family;document.getElementById('gallery-teacher').textContent=teacher;document.getElementById('gallery-index').textContent=String(index+1).padStart(2,'0').replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);}function stop(){clearInterval(timer);timer=null}function start(){stop();if(!paused&&!document.hidden)timer=setInterval(()=>show(index+1),5000)}function state(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'شروع نمایش خودکار':'توقف نمایش خودکار')}pause.onclick=()=>{paused=!paused;state();start()};document.getElementById('gallery-next').onclick=()=>{show(index+1);start()};document.getElementById('gallery-prev').onclick=()=>{show(index-1);start()};dots.forEach(d=>d.onclick=()=>{show(Number(d.dataset.gallery));start()});gallery.addEventListener('pointerenter',stop);gallery.addEventListener('pointerleave',start);gallery.addEventListener('focusin',stop);gallery.addEventListener('focusout',e=>{if(!gallery.contains(e.relatedTarget))start()});gallery.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){show(index+1);e.preventDefault()}else if(e.key==='ArrowRight'){show(index-1);e.preventDefault()}});document.addEventListener('visibilitychange',start);reduced.addEventListener('change',e=>{if(e.matches){paused=true;state();start()}});let x=null;gallery.addEventListener('touchstart',e=>{x=e.touches[0].clientX},{passive:true});gallery.addEventListener('touchend',e=>{if(x===null)return;const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>45){show(index+(dx<0?1:-1));start()}x=null},{passive:true});show(0);state();start()})();
